package com.medicine.reminder.controller; import com.medicine.reminder.dto.*; import com.medicine.reminder.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register") public Map<String,String> register(@Valid @RequestBody RegisterRequest r){auth.register(r);return Map.of("message","Registration successful. Please sign in.");}@PostMapping("/login") public Map<String,String> login(@Valid @RequestBody LoginRequest r){return auth.login(r);}}
